DROP VIEW IF EXISTS replset.vw_month_cashexp CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_cashexp AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     orgs_code,     orgs_name,     shop_code,     shop_name,     expwo_code,     expwo_name,     sum(amount) AS amount,     sum(amountvat) AS amountvat,     sum(amountwithvat) AS amountwithvat    FROM mvw_cashexp   GROUP BY (date_trunc('month'::text, date_period)), orgs_code, orgs_name, shop_code, shop_name, expwo_code, expwo_name;
